INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2025-11-06-slovenia-zierded-enacted', '2025-11-06', '2025-11', 'Slovenia published ZIERDED -- its first mandatory B2B e-invoicing law -- in the Official Gazette on 6 November 2025. The law sets a two-stage rollout: a certified "e-path" provider regime from 1 April 2027, and a universal B2B e-invoice exchange obligation from 1 January 2028, backed by real fines for non-compliance.', '<h3>🇸🇮 Slovenia enacts ZIERDED, its first B2B e-invoicing law</h3>
<p>On 6 November 2025, Slovenia published the Zakon o izmenjavi elektronskih računov in drugih elektronskih dokumentov (ZIERDED) in the Official Gazette (Uradni list RS, št. 85/2025) -- the country''s first mandatory business-to-business e-invoicing law. Slovenia''s public sector has required e-invoices since 2015 under a separate law, but until now there has been no general B2B mandate.</p>
<p>ZIERDED applies to every entity registered in Slovenia''s Business Register and every self-employed person, with no size threshold identified in the law''s text. It permits three exchange channels -- a certified e-path provider, a direct system-to-system link, or Peppol -- rather than mandating a single government platform, formatted to the e-SLOG 2.0 standard (aligned with EN 16931). The law explicitly ties itself to transposing elements of the EU''s ViDA directive (2025/516).</p>
<p>The rollout is staged: the certified e-path provider regime takes effect 1 April 2027, with the core mandatory exchange obligation following on 1 January 2028. Non-compliance draws fines under Art. 24 (EUR 1,000-3,000 for legal entities, lower amounts for sole proprietors and individuals) and a separate, lower Art. 25 range for consumer-invoice violations. Businesses trading with Slovenia have roughly two years to choose and test an exchange channel before the mandatory date.</p>', 'https://www.uradni-list.si/glasilo-uradni-list-rs/vsebina/2025-01-3032/zakon-o-izmenjavi-elektronskih-racunov-in-drugih-elektronskih-dokumentov-zierded', 1);
